<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class TripPlan extends Model { protected $fillable=['user_id','title','travel_date','start_latitude','start_longitude','start_address','start_time','end_time','total_distance','total_travel_minutes']; protected $casts=['travel_date'=>'date']; public function items(){return $this->hasMany(TripPlanItem::class)->orderBy('position');} }
